mapper.select:
SELECT o.order_id AS orderId,o.order_no AS orderNo,b.provider_id AS providerId, p.provider_code AS providerCode,b.provider_order_id AS providerOrderId, o.order_status AS localOrderStatus,o.payment_status AS paymentStatus, o.pay_amount AS localPayAmount,r.refund_id AS refundId,r.refund_status AS localRefundStatus, r.refund_amount AS localRefundAmount,rb.provider_refund_id AS providerRefundId, SUM(CASE WHEN et.ticket_status='UNUSED' THEN 1 ELSE 0 END) AS localValidTicketCount, COUNT(et.ticket_id) AS localTicketTotal FROM ticket_source_order_bridge b JOIN ticket_order o ON o.order_id=b.order_id JOIN ticket_source_provider p ON p.provider_id=b.provider_id LEFT JOIN refund_record r ON r.order_id=o.order_id LEFT JOIN ticket_source_refund_bridge rb ON rb.refund_id=r.refund_id LEFT JOIN electronic_ticket et ON et.order_id=o.order_id WHERE b.provider_id=#{providerId} AND b.provider_order_id IS NOT NULL AND b.provider_order_id<>''
AND o.order_id IN #{id}
GROUP BY o.order_id,o.order_no,b.provider_id,p.provider_code,b.provider_order_id, o.order_status,o.payment_status,o.pay_amount,r.refund_id,r.refund_status,r.refund_amount,rb.provider_refund_id ORDER BY o.order_id ASC
